import sys

def main():
    import sys
    input = sys.stdin.read().split()

    n = int(input[0])
    first_half = list(map(int, input[1:n//2+1]))
    x = int(input[n//2+1])

    prefix_sums = [0]
    current_sum = 0
    for income in first_half:
        current_sum += income
        prefix_sums.append(current_sum)

    def can_report(k):
        for i in range(len(prefix_sums) - k):
            if prefix_sums[i + k] - prefix_sums[i] + x * k <= 0:
                return False
        return True

    left, right = 1, n // 2 + 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if can_report(mid):
            result = mid
            left = mid + 1
        else:
            right = mid - 1

    print(result)

if __name__ == "__main__":
    main()
